render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(from = cfg$x, to = cfg$y), c("from", "to")); from_values <- as.character(data[[cfg$x]]); to_values <- as.character(data[[cfg$y]]); nodes <- sort(unique(c(from_values, to_values))); x <- seq_along(nodes); names(x) <- nodes; chart_open_device(cfg$outputPath, cfg$format); plot(x, rep(0, length(x)), type = "n", axes = FALSE, xlab = "", ylab = "", ylim = c(-0.05, 1.2), main = cfg$title %||% "弧线关系图"); segments(x, 0, x, 0.04, col = "#94A3B8"); text(x, -0.03, nodes, srt = 45, adj = 1, xpd = TRUE); for (i in seq_len(nrow(data))) { a <- x[from_values[i]]; b <- x[to_values[i]]; if (a > b) { z <- a; a <- b; b <- z }; h <- max(0.12, (b - a) * 0.18); tt <- seq(0, pi, length.out = 100); lines(seq(a, b, length.out = 100), h * sin(tt), col = cfg$color %||% "#0A84FF", lwd = 1.5); }; grDevices::dev.off(); cfg$outputPath }
